// Version A: inline repository call into controller
class OrderControllerA {
  constructor(private repo: OrderRepository) {}
  submit(order: any) {
    // minimal controller directly persists order
    this.repo.save(order)
  }
}

// Version B: keep a thin service layer that only forwards to repository
class OrderServiceB {
  constructor(private repo: OrderRepository) {}
  submit(order: any) { return this.repo.save(order) }
}

class OrderControllerB {
  constructor(private service: OrderServiceB) {}
  submit(order: any) { return this.service.submit(order) }
}
